#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "floyd-warshall.h"


/* Array initialization.
 *
 * Optimization notes:
 * - Parallelize the outer loop with OpenMP (if compiled with -fopenmp).
 *   Each (i,j) is written exactly once, so there are no data races.
 * - Hoist (i + j) into a temporary to avoid recomputing it three times.
 */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j;

  /* If compiled without OpenMP, this pragma is ignored by the compiler. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      int sum = i + j;
      DATA_TYPE v = (DATA_TYPE)((i * j) % 7 + 1);

      if ((sum % 13 == 0) || (sum % 7 == 0) || (sum % 11 == 0))
        v = (DATA_TYPE)999;

      path[i][j] = v;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("path");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, path[i][j]);
    }
  POLYBENCH_DUMP_END("path");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimization overview:
 * ----------------------
 * 1. For each k, we take a snapshot of:
 *      - the k-th row  : row_k[j] = path[k][j]
 *      - the k-th col. : col_k[i] = path[i][k]
 *
 *    These snapshots correspond to D^(k-1)[k][j] and D^(k-1)[i][k] in the
 *    classical Floyd–Warshall recurrence:
 *
 *      D^(k)[i][j] = min(D^(k-1)[i][j],
 *                        D^(k-1)[i][k] + D^(k-1)[k][j])
 *
 *    Using snapshots ensures that all updates for a fixed k use a
 *    consistent “previous” state, which both:
 *      - preserves the mathematical Floyd–Warshall result for graphs
 *        without negative cycles (the standard assumption), and
 *      - removes loop-carried dependencies inside the (i,j) loops.
 *
 * 2. With the row/column snapshots, each (i,j) update for a fixed k is
 *    independent. We exploit this by:
 *      - using an OpenMP parallel for with collapse(2) over (i,j),
 *        which distributes the 2D workload across threads.
 *      - maintaining simple, cache-friendly memory access patterns:
 *        path[i][j] is accessed in row-major order.
 *
 * 3. Extra memory:
 *      - Two temporary arrays of size O(N): row_k[N], col_k[N].
 *        Relative to the main N×N matrix, this overhead is O(1/N) and
 *        stays well below the allowed +50% memory overhead for realistic N.
 */
static
void kernel_floyd_warshall[[gnu::flatten, gnu::noinline]](int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;
  const int nPB = _PB_N;

  /* Temporary buffers holding a snapshot of the k-th row and column.
   * These are VLAs whose size matches the current problem size.
   */
  DATA_TYPE row_k[nPB];
  DATA_TYPE col_k[nPB];

#pragma scop
  for (k = 0; k < nPB; k++)
    {
      /* Snapshot k-th row: path[k][j] -> row_k[j] */
      for (j = 0; j < nPB; j++)
        row_k[j] = path[k][j];

      /* Snapshot k-th column: path[i][k] -> col_k[i] */
      for (i = 0; i < nPB; i++)
        col_k[i] = path[i][k];

      /* Parallel update of the whole matrix for this k.
       *
       * - Each (i,j) pair is updated exactly once.
       * - The right-hand side uses only row_k/col_k (snapshotted values),
       *   so there are no write-after-read or read-after-write hazards
       *   between different (i,j) iterations.
       *
       * If compiled without OpenMP, this pragma is ignored and the loop
       * executes sequentially with identical semantics.
       */
#pragma omp parallel for collapse(2) schedule(static)
      for (i = 0; i < nPB; i++)
        for (j = 0; j < nPB; j++)
          {
            DATA_TYPE via_k = col_k[i] + row_k[j];
            if (via_k < path[i][j])
              path[i][j] = via_k;
          }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(path)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(path);

  return 0;
}
