/* Array initialization.
 *
 * Optimizations:
 *  - Use a row pointer (path_i) to avoid repeated 2D indexing in the inner loop.
 *  - Hoist common subexpressions (i + j) so we compute the sum once per element.
 *
 * These changes do not alter the mathematical result, they only reduce
 * address arithmetic and integer operations.
 */
static
void init_array (int n,
                 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
  {
    /* Pointer to the current row improves cache locality and
       simplifies address calculations for the compiler. */
    DATA_TYPE *restrict path_i = path[i];

    for (j = 0; j < n; j++)
    {
      int base = (i * j) % 7 + 1;
      int sum  = i + j;

      if (sum % 13 == 0 || sum % 7 == 0 || sum % 11 == 0)
        base = 999;

      /* Implicit conversion from int to DATA_TYPE matches original code. */
      path_i[j] = base;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("path");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, path[i][j]);
    }
  POLYBENCH_DUMP_END("path");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 *  - Introduce a local `restrict`-qualified pointer to the 2D array. This
 *    gives the compiler stronger aliasing information and reduces index
 *    arithmetic.
 *  - Cache row pointers (for rows i and k) once per loop iteration instead of
 *    recomputing `path[i]` and `path[k]` in the innermost loop.
 *  - Replace the ternary min-expression with an explicit comparison and
 *    single load/store of the matrix element. This avoids reloading
 *    `path[i][j]` multiple times and usually maps directly to a conditional
 *    move or min instruction.
 *
 * Loop structure and update order (k, then i, then j) are kept identical to
 * the original implementation, so the numerical behavior is preserved exactly.
 */
static
void kernel_floyd_warshall[[gnu::flatten, gnu::noinline]](int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  /* Use the PolyBench-sized N (possibly different from the runtime n in
     some configurations) but cache it locally to avoid repeated loads. */
  const int nn = _PB_N;

  /* Create a local restrict-qualified view of the matrix.
     - The parameter `path` is the only reference to this storage in this
       function, and we do not use `path` again once `p` is defined, so
       the `restrict` promise is respected.
     - The second dimension uses the runtime `n` (VLA), matching the
       original declaration semantics. */
  DATA_TYPE (*restrict p)[n] = (DATA_TYPE (*restrict)[n])path;

  for (k = 0; k < nn; k++)
  {
    /* Cache pointer to the k-th row once per outer k-iteration. */
    DATA_TYPE *restrict pk = p[k];

    for (i = 0; i < nn; i++)
    {
      /* Pointer to the current row i. */
      DATA_TYPE *restrict pi = p[i];

      for (j = 0; j < nn; j++)
      {
        /* Compute candidate path length using vertex k as intermediate.
           We read pi[k] and pk[j] exactly as in the original code; the
           difference is only that we use row pointers instead of 2D
           indexing syntax. */
        DATA_TYPE via_k = pi[k] + pk[j];

        /* In-place relaxation: keep the shorter of the existing path and
           the candidate path via k. This is equivalent to:
              path[i][j] = path[i][j] < via_k ? path[i][j] : via_k;
           but avoids multiple loads of pi[j]. */
        if (via_k < pi[j])
          pi[j] = via_k;
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
