  /* Alias with 'restrict' to help compiler optimizations.
     The actual second dimension is 'n', as given in the parameter. */
  DATA_TYPE (*restrict path_)[n] = path;

  /* PolyBench may use _PB_N to run a smaller problem than the full
     allocated size 'n'. */
  const int nPB = _PB_N;

#pragma scop
  for (k = 0; k < nPB; k++)
    {
      /* Pointer to row k: heavily reused in the inner loops. */
      DATA_TYPE *restrict row_k = path_[k];

      /* As explained in the header comment above, all iterations with
         i == k or j == k are mathematically no-ops for this benchmark
         (due to path[k][k] >= 1) and can be skipped.  This also makes
         row k and column k read-only inside the parallel region. */

#ifdef _OPENMP
#pragma omp parallel for schedule(static) private(j)
#endif
      for (i = 0; i < nPB; i++)
        {
          /* Skip row k: its updates would not change the data. */
          if (i == k)
            continue;

          DATA_TYPE *restrict row_i = path_[i];
          /* path[i][k] is invariant across all j for fixed (k,i). */
          const DATA_TYPE path_ik = row_i[k];

          /* Process columns j < k. There is no dependency across j,
             so this loop is a good SIMD/vectorization target. */
#ifdef _OPENMP
#pragma omp simd
#endif
          for (j = 0; j < k; j++)
            {
              const DATA_TYPE via_k = path_ik + row_k[j];
              if (via_k < row_i[j])
                row_i[j] = via_k;
            }

          /* Process columns j > k.  (j == k is skipped since it would
             only perform a no-op update on path[i][k].) */
#ifdef _OPENMP
#pragma omp simd
#endif
          for (j = k + 1; j < nPB; j++)
            {
              const DATA_TYPE via_k = path_ik + row_k[j];
              if (via_k < row_i[j])
                row_i[j] = via_k;
            }
        }
    }
#pragma endscop

}


