#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "floyd-warshall.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j;

  /* Use row pointers to improve locality and help the compiler
     with alias analysis. The semantics are identical to the
     original double-indexed version. */
  for (i = 0; i < n; i++)
  {
    DATA_TYPE* __restrict__ row_i = path[i];
    for (j = 0; j < n; j++)
    {
      int sum = i + j;
      DATA_TYPE val = (DATA_TYPE)(i * j % 7 + 1);

      if ((sum % 13 == 0) || (sum % 7 == 0) || (sum % 11 == 0))
        row_i[j] = (DATA_TYPE)999;
      else
        row_i[j] = val;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(path,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("path");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, path[i][j]);
    }
  POLYBENCH_DUMP_END("path");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Keep the k-loop outermost to preserve Floyd–Warshall semantics.
   - Parallelize the i-loop for each fixed k using OpenMP (if enabled
     at compile time). Without -fopenmp these pragmas are ignored and
     the code remains sequential.
   - Use row pointers (path[k], path[i]) to improve cache locality and
     enable more aggressive compiler vectorization.
   - Hoist path[i][k] out of the inner j-loop into a scalar (dik).
     This is safe because, for this benchmark’s initialization, the
     update at j == k never changes path[i][k] (it would compute
     min(dik, dik + path[k][k]) with path[k][k] >= 0, so dik is kept).
   - Add an OpenMP 'simd' hint on the innermost j-loop to promote
     vectorization when OpenMP SIMD is enabled.
*/
static
void kernel_floyd_warshall[[gnu::flatten, gnu::noinline]](int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  /* Effective problem size, following PolyBench’s macro convention. */
  const int n_eff = _PB_N;

#pragma scop
  /* Parallel region (only active if compiled with OpenMP).
     Without OpenMP support, this becomes a simple lexical block. */
#pragma omp parallel
  {
    /* Outer k-loop must remain sequential across all threads to
       preserve algorithmic dependencies. Each k step uses results
       from all previous k' < k steps. */
    for (int k = 0; k < n_eff; ++k)
    {
      /* Row k is read-only within this k-iteration. */
      DATA_TYPE const * __restrict__ row_k = path[k];

      /* Distribute rows i across threads.
         For fixed k, each (i,j) pair is updated independently, and
         distinct i’s write to disjoint rows, so there are no data
         races. The implicit barrier at the end of 'omp for' ensures
         all updates for this k complete before k advances. */
#pragma omp for schedule(static)
      for (int i = 0; i < n_eff; ++i)
      {
        DATA_TYPE* __restrict__ row_i = path[i];

        /* path[i][k] is invariant over j for the reasons discussed
           above, so we load it once into a scalar. This reduces
           memory traffic and clarifies the dependency structure
           for the compiler. */
        const DATA_TYPE dik = row_i[k];

        /* Each j-iteration is independent given fixed (k,i). This hint
           enables vectorization with OpenMP SIMD (if supported). When
           OpenMP is disabled, it is treated as a normal loop pragma
           with no semantic effect. */
#pragma omp simd
        for (int j = 0; j < n_eff; ++j)
        {
          const DATA_TYPE via_k = dik + row_k[j];
          /* Standard Floyd–Warshall relaxation:
             path[i][j] = min(path[i][j], path[i][k] + path[k][j]); */
          if (via_k < row_i[j])
            row_i[j] = via_k;
        }
      } /* end for i (omp for, implicit barrier here) */
    }   /* end for k */
  }     /* end parallel region */
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(path, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(path));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_floyd_warshall (n, POLYBENCH_ARRAY(path));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(path)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(path);

  return 0;
}
